async function pollLive(){if(document.hidden)return;const candidates=liveCandidates();if(!candidates.length)return;const requests=new Map(),json=path=>{if(!requests.has(path))requests.set(path,fetch(`https://site.api.espn.com/apis/${path}`,{cache:'no-store'}).then(response=>{if(!response.ok)throw new Error(`ESPN ${response.status}`);return response.json()}));return requests.get(path)},read=async match=>{const slug=LEAGUES[match.league][4],dates=[match.date,previousDate(match.date)];for(const date of dates){const data=await json(`site/v2/sports/soccer/${slug}/scoreboard?dates=${date.replaceAll('-','')}`).catch(()=>null),entry=data&&liveEntryFromPayload(data,match.id);if(entry)return entry}const summary=await json(`site/v2/sports/soccer/${slug}/summary?event=${String(match.id).replace('espn-','')}`).catch(()=>null);return summary&&liveEntryFromPayload(summary,match.id)};let changed=false,finished=0;await Promise.all(candidates.map(async match=>{try{const entry=await read(match);if(!entry)throw new Error('Match ESPN absent');const before=state.live[match.id],different=!before||['state','clock','home','away','completed'].some(key=>before[key]!==entry[key]);if(different||state.liveErrors[match.id])changed=true;if(before?.state==='in'&&entry.state==='in'&&entry.home+entry.away>before.home+before.away){state.goal={id:match.id,until:Date.now()+5000};toast(`But · ${match.home} ${entry.home} : ${entry.away} ${match.away}`)}state.live[match.id]=entry;delete state.liveErrors[match.id];if(entry.completed&&!match.completed){Object.assign(match,{completed:true,status:'Terminé',homeScore:entry.home,awayScore:entry.away});state.results.push({id:match.id,date:match.date,home:match.home,away:match.away,homeScore:entry.home,awayScore:entry.away,completed:true});finished++}}catch(error){if(!state.liveErrors[match.id])changed=true;state.liveErrors[match.id]=Date.now();console.warn(`Direct indisponible pour ${match.id}`,error)}}));if(finished){const settled=settlePendingBets(state.results);render();if(settled)toast(`${settled} pari${settled>1?'s':''} réglé${settled>1?'s':''} au coup de sifflet final`)}else if(changed){renderMatches();renderHistory()}else tickCountdowns()}
// Défi du jour (BET-54) : 4 matchs imposés, cotes figées, pronostic 1N2 gratuit (aucune mise), fermé au coup d'envoi de chaque match.
