$('#share-combo').addEventListener('click',async()=>{if(!state.ticket.length)return;const total=state.ticket.reduce((product,item)=>product*item.odd,1),independent=state.betMode!=='combined',type=state.betMode==='single'?'Paris simples':state.betMode==='multiple'?'Paris multiples':`Combiné ${$('#risk-profile').selectedOptions[0].text}`,summary=independent?`${state.ticket.length} paris indépendants`:`Cote totale : ${total.toFixed(2)}`,text=`BetMaster · ${type}\n${state.ticket.map((item,index)=>`${index+1}. ${item.match}\n   ${item.label} @ ${item.odd.toFixed(2)}`).join('\n')}\n${summary}\nSimulation uniquement · 18+ · Jouez responsablement.`;try{if(navigator.share)await navigator.share({title:`Mon ticket BetMaster · ${type}`,text});else await navigator.clipboard.writeText(text);toast(navigator.share?'Ticket partagé':'Ticket copié dans le presse-papiers')}catch(error){if(error?.name!=='AbortError')toast('Impossible de partager ce ticket')}});
$('#place-bet').addEventListener('click',async()=>{
  if(!accountAuthenticated){openJoin('login');toast('Connectez-vous ou créez un compte pour enregistrer ce pari');return}
  if(!state.serverReady){toast('Les paris certifiés sont momentanément indisponibles');return}
  const button=$('#place-bet'),stake=Number($('#stake').value),single=state.betMode==='single',multiple=state.betMode==='multiple',totalStake=stake*(single?state.ticket.length:1);
  if(button.dataset.busy||!state.ticket.length||stake<=0||totalStake>state.bankroll)return;
  if(state.ticket.some(item=>!String(item.matchId).startsWith('espn-'))){toast('Les matchs ajoutés à la main ou de démonstration ne peuvent pas être pariés');return}
  const leg=item=>({matchId:item.matchId,key:item.key,odd:item.odd}),formula=multiple?$('#system-formula').value:null,signature=JSON.stringify([state.betMode,stake,formula,state.ticket.map(leg)]);
  if(multiple&&!systemLines(state.ticket,formula).length)return;
  if(betAttempt?.signature!==signature)betAttempt={signature,refs:state.ticket.map(()=>crypto.randomUUID?.()??null)};
  button.dataset.busy='1';button.disabled=true;let placed=0,failure=null;
  try{if(single)for(const [index,item] of state.ticket.entries()){await accountApi.placeBet({selections:[leg(item)],stake,betType:'single',countsGeneral:state.countsLeague,clientRef:betAttempt.refs[index]});placed++}else if(multiple){await accountApi.placeBet({selections:state.ticket.map(leg),stake,betType:'multiple',formula,clientRef:betAttempt.refs[0]});placed=1}else{await accountApi.placeBet({selections:state.ticket.map(leg),stake,betType:state.ticket.length>1?'combined':'single',countsGeneral:state.countsLeague,clientRef:betAttempt.refs[0]});placed=1}}catch(error){failure=error}
  delete button.dataset.busy;
  if(failure){toast(placed?`${placed} pari${placed>1?'s':''} placé${placed>1?'s':''}, puis : ${failure.message}`:failure.message);if(['COTE_CHANGEE','MATCH_COMMENCE','MATCH_INCONNU'].includes(failure.code))loadLiveFixtures()}
  if(placed)betAttempt=null;
  await accountApi.refreshServer();
  if(!placed){renderTicket();return}
  if(!failure)state.ticket=[];render();if(!failure){setActiveTab('bankroll',true);toast(single?`${placed} pari${placed>1?'s':''} simple${placed>1?'s':''} certifié${placed>1?'s':''}`:multiple?'Pari système certifié et enregistré':'Combiné certifié et enregistré')}
});
